completions.bash:
# drop: autocompletado para bash. Cárgalo con:
#   eval "$(drop completion bash)"
_drop() {
  local cur prev cmd flags i
  COMPREPLY=()
  cur="${COMP_WORDS[COMP_CWORD]}"
  prev="${COMP_WORDS[COMP_CWORD-1]}"
  cmd=""
  for ((i = 1; i < COMP_CWORD; i++)); do
    case "${COMP_WORDS[i]}" in
      -*) ;;
      *) cmd="${COMP_WORDS[i]}"; break ;;
    esac
  done
  case "$prev" in
    -o|--out) COMPREPLY=( $(compgen -d -- "$cur") ); return ;;
    -s|--server|--text|--name|--expire|--limit|--only|-p|--port|-H|--host|-t|--time) return ;;
    completion) COMPREPLY=( $(compgen -W "bash zsh fish powershell" -- "$cur") ); return ;;
  esac
  if [[ -z "$cmd" ]]; then
    if [[ "$cur" == -* ]]; then
      COMPREPLY=( $(compgen -W "--server --update --help --version" -- "$cur") )
    else
      COMPREPLY=( $(compgen -W "send recv speed serve update install uninstall completion verify-web" -- "$cur") $(compgen -f -- "$cur") )
    fi
    return
  fi
  case "$cmd" in
    send) flags="--server --text --clipboard --name --once --expire --no-qr --yes --port --limit --relay --update --help --version" ;;
    recv) flags="--server --out --stdout --overwrite --no-resume --only --limit --relay --update --help --version" ;;
    speed) flags="--server --port --relay --direct-only --time --update --help --version" ;;
    serve) flags="--server --port --host --update --help --version" ;;
    update) flags="--server --force --allow-unsigned --skip-verify --update --help --version" ;;
    install) flags="--server --update --help --version" ;;
    uninstall) flags="--server --update --help --version" ;;
    completion) flags="--server --update --help --version" ;;
    verify-web) flags="--server --update --help --version" ;;
    *) flags="" ;;
  esac
  if [[ "$cur" == -* ]]; then
    COMPREPLY=( $(compgen -W "$flags" -- "$cur") )
  elif [[ "$cmd" == "send" ]]; then
    COMPREPLY=( $(compgen -f -- "$cur") )
  fi
}
complete -o filenames -F _drop drop

completions.powershell:
# drop: autocompletado para PowerShell. Cárgalo con:
#   drop completion powershell | Out-String | Invoke-Expression
# o añade esa línea a tu $PROFILE.
Register-ArgumentCompleter -Native -CommandName drop -ScriptBlock {
  param($wordToComplete, $commandAst, $cursorPosition)
  $cmds = @(
    @{ n = 'send'; d = 'Envía archivos, carpetas o stdin (-)' }
    @{ n = 'recv'; d = 'Recibe con un código o enlace' }
    @{ n = 'speed'; d = 'Mide la velocidad entre dos CLI' }
    @{ n = 'serve'; d = 'Levanta el servidor web y de señalización local' }
    @{ n = 'update'; d = 'Instala la última versión' }
    @{ n = 'install'; d = 'Instala drop en el sistema' }
    @{ n = 'uninstall'; d = 'Desinstala drop' }
    @{ n = 'completion'; d = 'Imprime el autocompletado de un shell' }
    @{ n = 'verify-web'; d = 'Comprueba que la web sirve el código del repositorio' }
  )
  $flags = @(
    @{ n = '--server'; c = @(); d = 'Servidor de señalización' }
    @{ n = '-s'; c = @(); d = 'Servidor de señalización' }
    @{ n = '--out'; c = @('recv'); d = 'Carpeta de destino (- es stdout)' }
    @{ n = '-o'; c = @('recv'); d = 'Carpeta de destino (- es stdout)' }
    @{ n = '--stdout'; c = @('recv'); d = 'Vuelca lo recibido a stdout' }
    @{ n = '--overwrite'; c = @('recv'); d = 'Sobrescribe lo que ya exista' }
    @{ n = '--no-resume'; c = @('recv'); d = 'No reanuda un .part' }
    @{ n = '--only'; c = @('recv'); d = 'Solo los archivos que casen (*.jpg,fotos/**)' }
    @{ n = '--text'; c = @('send'); d = 'Envía ese texto como message.txt' }
    @{ n = '--clipboard'; c = @('send'); d = 'Envía el portapapeles' }
    @{ n = '--name'; c = @('send'); d = 'Nombre para lo que viene de stdin' }
    @{ n = '--once'; c = @('send'); d = 'Cierra tras la primera descarga' }
    @{ n = '--expire'; c = @('send'); d = 'Caduca pasado ese tiempo (90s, 10m, 2h)' }
    @{ n = '--no-qr'; c = @('send'); d = 'No pinta el QR' }
    @{ n = '--yes'; c = @('send'); d = 'No pide confirmación por receptor' }
    @{ n = '-y'; c = @('send'); d = 'No pide confirmación por receptor' }
    @{ n = '--port'; c = @('send','speed','serve'); d = 'Puerto TCP local' }
    @{ n = '-p'; c = @('send','speed','serve'); d = 'Puerto TCP local' }
    @{ n = '--host'; c = @('serve'); d = 'Dirección de escucha' }
    @{ n = '-H'; c = @('serve'); d = 'Dirección de escucha' }
    @{ n = '--limit'; c = @('send','recv'); d = 'Límite de ancho de banda (500K, 10M)' }
    @{ n = '--relay'; c = @('send','recv','speed'); d = 'Fuerza el relay por el servidor' }
    @{ n = '--direct-only'; c = @('speed'); d = 'Solo TCP directo' }
    @{ n = '--time'; c = @('speed'); d = 'Segundos por fase' }
    @{ n = '-t'; c = @('speed'); d = 'Segundos por fase' }
    @{ n = '--force'; c = @('update'); d = 'Reinstala aunque esté al día' }
    @{ n = '--allow-unsigned'; c = @('update'); d = 'Acepta una release sin firma' }
    @{ n = '--skip-verify'; c = @('update'); d = 'Sin firma ni hash (no recomendado)' }
    @{ n = '--update'; c = @(); d = 'Igual que "drop update"' }
    @{ n = '--help'; c = @(); d = 'Muestra la ayuda' }
    @{ n = '-h'; c = @(); d = 'Muestra la ayuda' }
    @{ n = '--version'; c = @(); d = 'Muestra la versión' }
    @{ n = '-v'; c = @(); d = 'Muestra la versión' }
  )
  $words = $commandAst.CommandElements | Select-Object -Skip 1 | ForEach-Object { $_.ToString() }
  $cmd = $words | Where-Object { $_ -notlike '-*' } | Select-Object -First 1
  if ($cmd -eq 'completion') {
    'bash','zsh','fish','powershell' -split ',' | Where-Object { $_ -like "$wordToComplete*" } | ForEach-Object {
      [System.Management.Automation.CompletionResult]::new($_, $_, 'ParameterValue', $_)
    }
    return
  }
  if ($wordToComplete -like '-*') {
    $flags | Where-Object { $_.n -like "$wordToComplete*" -and ($_.c.Count -eq 0 -or $_.c -contains $cmd) } | ForEach-Object {
      [System.Management.Automation.CompletionResult]::new($_.n, $_.n, 'ParameterName', $_.d)
    }
    return
  }
  if (-not $cmd) {
    $cmds | Where-Object { $_.n -like "$wordToComplete*" } | ForEach-Object {
      [System.Management.Automation.CompletionResult]::new($_.n, $_.n, 'ParameterValue', $_.d)
    }
  }
}

